head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징


scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.gDtecDd;
scwin.gSeq;
scwin.gChgStatCd;
scwin.regMode; // 'REG', 'MOD'
scwin.gComAbbrv;
scwin.gChgTpNm;
scwin.gStrtDd;
scwin.gChgRsnNm;
scwin.gMisc;
scwin.vScrenID = 'ULDSTF37406.xml';
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};



//페이지 로딩 시 필요한 변수 초기화
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();

    //조회일자 오늘로 셋팅
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SchDate.setValue(vCurDate);

    //부서코드 로그인 사용자 부서로 셋팅
    $c.stf.setObjectValue(cmb_DEP_CD, js_dep_cd);
    if ($c.stf.getObjectValue(cmb_DEP_CD) == '') {
        cmb_DEP_CD.setSelectedIndex(0);
    }
};
scwin.fn_Search = function() {
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd);
    var vSCH_DD = $c.stf.getObjectValue(edt_SchDate);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    var vSTAT_CD = $c.stf.getObjectValue(cmb_stat_cd);
    var url = "/ByPass.do?method=listDesignExcludeSecu";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCH_DD=" + vSCH_DD;
    url += "&STAT_CD=" + $c.stf.trim(vSTAT_CD);
    url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.gIsurCd = dts_List.getCellData(eval(row), "ISUR_CD");
    scwin.gDtecDd = dts_List.getCellData(eval(row), "DTEC_DD");
    scwin.gSeq = dts_List.getCellData(eval(row), "SEQ");
    scwin.gChgStatCd = dts_List.getCellData(eval(row), "PRE_REVW_EXMPT_OBJ_CHG_STAT_CD");
    scwin.gComAbbrv = dts_List.getCellData(eval(row), "COM_ABBRV");
    scwin.gChgTpNm = dts_List.getCellData(eval(row), "PRE_REVW_EXMPT_OBJ_CHG_TP_NM");
    scwin.gStrtDd = dts_List.getCellData(eval(row), "STRT_DD");
    scwin.gChgRsnNm = dts_List.getCellData(eval(row), "PRE_REVW_EXMPT_CHG_RSN_NM");
    scwin.gMisc = dts_List.getCellData(eval(row), "MISC");
    if (scwin.gChgStatCd == "10") {
        scwin.regMode = 'MOD'; //수정 및 검토모드

    } else if (scwin.gChgStatCd == "20") {
        scwin.regMode = 'APP'; //승인모드

    } else {
        scwin.regMode = 'VIEW'; //승인완료모드

    }
    if (colid == "PRE_REVW_EXMPT_OBJ_CHG_STAT_NM") {
        // 승인상태 클릭 시
        if (scwin.gChgStatCd == "10") {
            var url = "/dsclmgt/ULDSTF37407.gfm";
            var winTitle = "사전확인절차 면제 대상법인 지정/제외";
            await $c.frame.CreateDialogFrame("ULDSTF37407", url, winTitle, 100, 100, 730, 350, "window");
        } else {
            var url = "/dsclmgt/ULDSTF37307.gfm";
            var winTitle = "사전확인절차 면제 대상법인 지정/제외";
            await $c.frame.CreateDialogFrame("ULDSTF37307", url, winTitle, 100, 100, 720, 250, "window");
        }
    }
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_SchDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "사전확인절차 면제대상 변경현황", "", "8");
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();

    //회사정보 로딩
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Search();
};
scwin.btn_New_onclick = async function() {
    scwin.regMode = "REG";
    var url = "/dsclmgt/ULDSTF37407.gfm";
    var winTitle = "사전확인절차 면제 대상법인 지정/제외";
    await $c.frame.CreateDialogFrame("ULDSTF37407", url, winTitle, 100, 100, 725, 420, "window");
};
